public Option build(String opt) throws IllegalArgumentException {
    if (opt == null || opt.trim().isEmpty()) {
        throw new IllegalArgumentException("Option short name cannot be null or empty.");
    }

    // Determine if the option has arguments based on numberOfArgs.
    // This is more robust than relying on a constructor's default 'hasArg' assumption.
    boolean hasArgsFlag = (numberOfArgs != Option.UNINITIALIZED && numberOfArgs != 0);

    Option option;
    if (longopt != null) {
        // Use the constructor that includes the long option name if it was provided.
        option = new Option(opt, longopt, hasArgsFlag, description);
    } else {
        // Use the constructor without a long option name.
        option = new Option(opt, hasArgsFlag, description);
    }

    // Set remaining properties.
    // The longopt is already handled by the constructor choice above.
    option.setRequired(required);
    option.setOptionalArg(optionalArg);
    option.setArgs(numberOfArgs);
    option.setType(type);
    // Only set value separator if it was explicitly configured (i.e., not its default char value 0).
    if (valuesep != 0) {
        option.setValueSeparator(valuesep);
    }
    option.setArgName(argName);

    // No OptionBuilder.reset() is needed as this is an instance-based builder.
    // Each builder instance is independent and starts with a clean state.

    return option;
}
