class Base64 {
    private byte[] buffer;
    private int pos; // write position in buffer
    private int readPos; // read position in buffer
    private int currentSize; // number of bytes available to read
    private boolean eofSignaled = false; // Flag to indicate EOF has been signaled to the processor

    public Base64() {
        this.buffer = new byte[8192]; // Example internal buffer
        this.pos = 0;
        this.readPos = 0;
        this.currentSize = 0;
    }

    public boolean hasData() {
        return currentSize > 0;
    }

    // Simulates BaseNCodec's encode/decode for streaming input.
    // len = -1 indicates EOF for the input stream, triggering internal flushing.
    public void encode(byte[] input, int offset, int len) {
        if (len == -1) {
            eofSignaled = true;
            // In a real BaseNCodec, this would trigger flushing of remaining data
            // into the internal buffer. For this placeholder, we just mark EOF.
            return;
        }
        if (len <= 0) return;

        // Simulate encoding: just copy input to internal buffer for simplicity.
        // In reality, this would perform Base64 encoding and fill the buffer.
        int spaceAvailable = buffer.length - pos;
        int bytesToProcess = Math.min(len, spaceAvailable);
        if (bytesToProcess > 0) {
            System.arraycopy(input, offset, buffer, pos, bytesToProcess);
            pos += bytesToProcess;
            currentSize += bytesToProcess; // Assuming 1:1 for simplicity
        }
        // If buffer is full, a real BaseNCodec would expand or process and shift.
    }

    public void decode(byte[] input, int offset, int len) {
        if (len == -1) {
            eofSignaled = true;
            // In a real BaseNCodec, this would trigger flushing of remaining data.
            return;
        }
        if (len <= 0) return;

        // Simulate decoding: just copy input to internal buffer for simplicity.
        // In reality, this would perform Base64 decoding and fill the buffer.
        int spaceAvailable = buffer.length - pos;
        int bytesToProcess = Math.min(len, spaceAvailable);
        if (bytesToProcess > 0) {
            System.arraycopy(input, offset, buffer, pos, bytesToProcess);
            pos += bytesToProcess;
            currentSize += bytesToProcess; // Assuming 1:1 for simplicity
        }
    }

    public int readResults(byte[] output, int offset, int len) {
        if (currentSize == 0) {
            return eofSignaled ? -1 : 0; // Return -1 if EOF signaled and no data, else 0
        }
        int bytesToRead = Math.min(len, currentSize);
        System.arraycopy(buffer, readPos, output, offset, bytesToRead);
        readPos += bytesToRead;
        currentSize -= bytesToRead;

        if (currentSize == 0) {
            // Buffer is empty, reset positions
            pos = 0;
            readPos = 0;
        }
        return bytesToRead;
    }
