import java.io.ObjectInputStream;
import java.io.ObjectStreamClass;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Level;
import java.util.logging.Logger;

// Assuming UnsafeAllocator is an abstract class or interface with newInstance method.
// For the purpose of this corrected implementation, we define a minimal interface.
interface UnsafeAllocator {
    <T> T newInstance(Class<T> c) throws Exception;
}

// Renamed the class to avoid conflict with the UnsafeAllocator interface/abstract class
// and to better reflect its role as a factory.
public class UnsafeAllocatorFactory {
    private static final Logger logger = Logger.getLogger(UnsafeAllocatorFactory.class.getName());

    public static UnsafeAllocator create() {
        // Collect all exceptions encountered during the discovery phase for better diagnostics.
        List<Throwable> suppressedExceptions = new ArrayList<>();

        // Attempt 1: Standard JVM (sun.misc.Unsafe)
        try {
            Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
            Field f = unsafeClass.getDeclaredField("theUnsafe");
            f.setAccessible(true); // Bypass access checks for the private field
            final Object unsafe = f.get(null); // Get the singleton Unsafe instance
            final Method allocateInstance = unsafeClass.getMethod("allocateInstance", Class.class);
            logger.log(Level.FINE, "Successfully initialized UnsafeAllocator using sun.misc.Unsafe.");
            return new UnsafeAllocator() {
                @Override
                @SuppressWarnings("unchecked")
                public <T> T newInstance(Class<T> c) throws Exception {
                    if (c == null) {
                        throw new IllegalArgumentException("Class to instantiate cannot be null.");
                    }
                    return (T) allocateInstance.invoke(unsafe, c);
                }
            };
        } catch (Exception e) {
            logger.log(Level.FINE, "Failed to initialize UnsafeAllocator using sun.misc.Unsafe.", e);
            suppressedExceptions.add(e);
        }

        // Attempt 2: Dalvik/Android (post-Gingerbread, ObjectStreamClass)
        try {
            Method getConstructorId = ObjectStreamClass.class
                .getDeclaredMethod("getConstructorId", Class.class);
            getConstructorId.setAccessible(true); // Bypass access checks
            // Obtain a constructor ID for Object.class, which is a known hack for constructor-less allocation on Dalvik.
            final int constructorId = (Integer) getConstructorId.invoke(null, Object.class);
            final Method newInstance = ObjectStreamClass.class
                .getDeclaredMethod("newInstance", Class.class, int.class);
            newInstance.setAccessible(true); // Bypass access checks
            logger.log(Level.FINE, "Successfully initialized UnsafeAllocator using ObjectStreamClass (Dalvik post-Gingerbread).");
            return new UnsafeAllocator() {
                @Override
                @SuppressWarnings("unchecked")
                public <T> T newInstance(Class<T> c) throws Exception {
                    if (c == null) {
                        throw new IllegalArgumentException("Class to instantiate cannot be null.");
                    }
                    return (T) newInstance.invoke(null, c, constructorId);
                }
            };
        } catch (Exception e) {
            logger.log(Level.FINE, "Failed to initialize UnsafeAllocator using ObjectStreamClass (Dalvik post-Gingerbread).", e);
            suppressedExceptions.add(e);
        }

        // Attempt 3: Dalvik/Android (pre-Gingerbread, ObjectInputStream)
        try {
            final Method newInstance = ObjectInputStream.class
                .getDeclaredMethod("newInstance", Class.class, Class.class);
            newInstance.setAccessible(true); // Bypass access checks
            logger.log(Level.FINE, "Successfully initialized UnsafeAllocator using ObjectInputStream (Dalvik pre-Gingerbread).");
            return new UnsafeAllocator() {
                @Override
                @SuppressWarnings("unchecked")
                public <T> T newInstance(Class<T> c) throws Exception {
                    if (c == null) {
                        throw new IllegalArgumentException("Class to instantiate cannot be null.");
                    }
                    // Pass Object.class as the constructorClass, a known hack for constructor-less allocation.
                    return (T) newInstance.invoke(null, c, Object.class);
                }
            };
        } catch (Exception e) {
            logger.log(Level.FINE, "Failed to initialize UnsafeAllocator using ObjectInputStream (Dalvik pre-Gingerbread).", e);
            suppressedExceptions.add(e);
        }

        // Fallback: No suitable unsafe allocator found.
        logger.log(Level.WARNING, "No suitable unsafe allocator mechanism found on this platform. Object allocation without constructor will fail.");
        return new UnsafeAllocator() {
            @Override
            public <T> T newInstance(Class<T> c) {
                if (c == null) {
                    throw new IllegalArgumentException("Class to instantiate cannot be null.");
                }
                UnsupportedOperationException uoe = new UnsupportedOperationException(
                    "Cannot allocate " + c.getName() + " without calling a constructor. No suitable unsafe allocator found on this platform."
                );
                // Add all collected exceptions as suppressed exceptions for better diagnostics.
                for (Throwable suppressed : suppressedExceptions) {
                    uoe.addSuppressed(suppressed);
                }
                throw uoe;
            }
        };
    }
}
