public JsonWriter value(Number value) throws IOException {
    if (value == null) {
      return nullValue();
    }

    // Delegate to specific value methods for common Number types.
    // This ensures consistent handling, leverages existing optimized logic,
    // and correctly applies lenient/non-lenient checks for these types.
    if (value instanceof Double) {
        // Calls public JsonWriter value(double value)
        return value(((Double) value).doubleValue());
    }
    if (value instanceof Float) {
        // Convert Float to Double to use the existing double handler,
        // as JSON numbers are typically double-precision and to avoid float precision issues.
        return value(((Float) value).doubleValue());
    }
    if (value instanceof Long) {
        // Calls public JsonWriter value(long value)
        return value(((Long) value).longValue());
    }
    // For other Number types (e.g., Integer, Short, Byte, BigDecimal, BigInteger,
    // or custom Number implementations), proceed with the generic toString() approach.

    writeDeferredName();

    String stringRepresentation = value.toString();

    // This check is still necessary for other Number types (like BigDecimal, BigInteger,
    // or custom Number implementations) whose toString() might produce these non-finite strings.
    // For Double/Float/Long, this check is now implicitly handled by their specific value methods.
    if (!lenient
        && (stringRepresentation.equals("-Infinity") || stringRepresentation.equals("Infinity") || stringRepresentation.equals("NaN"))) {
      throw new IllegalArgumentException("Numeric values must be finite, but was " + value);
    }

    beforeValue(false);
    out.append(stringRepresentation);
