public static String join(Object[] array, String separator, int startIndex, int endIndex) {
    if (array == null) {
        return null;
    }
    if (separator == null) {
        separator = EMPTY; // Assuming EMPTY is defined as ""
    }

    // Validate indices against array bounds
    if (startIndex < 0) {
        throw new IndexOutOfBoundsException("startIndex cannot be negative: " + startIndex);
    }
    if (endIndex > array.length) {
        throw new IndexOutOfBoundsException("endIndex cannot be greater than array length: " + endIndex + " > " + array.length);
    }

    int noOfItems = (endIndex - startIndex);
    if (noOfItems <= 0) {
        return EMPTY; // Handles cases where startIndex >= endIndex
    }

    // Improved StringBuilder capacity estimation
    // A reasonable heuristic: assume an average string length of 16 characters per item.
    // This avoids accessing array elements for length estimation before they are processed.
    int capacity = noOfItems * 16;
    if (noOfItems > 1) {
        capacity += separator.length() * (noOfItems - 1);
    }
    StringBuilder buf = new StringBuilder(capacity);

    for (int i = startIndex; i < endIndex; i++) {
        if (i > startIndex) {
            buf.append(separator);
        }
        if (array[i] != null) {
            buf.append(array[i]);
        }
    }
    return buf.toString();
}
