@Override
public int translate(CharSequence input, int index, Writer out) throws IOException {
    // Robustness: Null checks for input and output writer
    if (out == null) {
        throw new NullPointerException("The Writer must not be null.");
    }
    if (input == null) {
        return 0; // As per CharSequenceTranslator contract, null input means no translation.
    }

    // Robustness: Check if there's enough characters for at least "&#"
    // An entity must be at least 4 characters long (e.g., "&#0;")
    if (index < 0 || index >= input.length() - 2) { // Need at least input[index], input[index+1], input[index+2]
        return 0;
    }

    // Check for the start of a numeric entity: "&#"
    if (input.charAt(index) == '&' && input.charAt(index + 1) == '#') {
        int start = index + 2; // Position after "&#"
        boolean isHex = false;

        // Robustness: Check if there's at least one character after "&#"
        // This character could be 'x'/'X' or the first digit.
        if (start >= input.length()) {
            return 0; // Malformed entity: "&#" at end of string, no content or semicolon.
        }

        char firstCharAfterHash = input.charAt(start);
        if (firstCharAfterHash == 'x' || firstCharAfterHash == 'X') {
            // It's a hexadecimal entity (e.g., "&#x7B;")
            start++; // Move past 'x' or 'X'
            isHex = true;

            // Robustness: Check if there's at least one character after "&#x"
            // This character must be a digit or the semicolon.
            if (start >= input.length()) {
                return 0; // Malformed entity: "&#x" at end of string, no content or semicolon.
            }
        }

        int end = start;
        // Robustness: Find the closing ';' while staying within bounds
        while (end < input.length() && input.charAt(end) != ';') {
            end++;
        }

        // Robustness: If ';' was not found, it's a malformed entity
        if (end == input.length()) {
            return 0;
        }

        // Robustness: Check if there's actual content between start and end (e.g., "&#;" or "&#x;")
        if (start == end) {
            return 0; // Empty entity, e.g., "&#;" or "&#x;"
        }

        int entityValue;
        try {
            String numericPart = input.subSequence(start, end).toString();
            if (isHex) {
                entityValue = Integer.parseInt(numericPart, 16);
            } else {
                entityValue = Integer.parseInt(numericPart, 10);
            }
        } catch (NumberFormatException nfe) {
            // Robustness: If the numeric part is not a valid number, it's not a valid entity
            return 0;
        }

        // Robustness: Check for valid Unicode code point range
        // HTML/XML entities are typically within valid Unicode range (0 to 0x10FFFF).
        if (entityValue < Character.MIN_CODE_POINT || entityValue > Character.MAX_CODE_POINT) {
             return 0; // Not a valid Unicode code point, treat as malformed
        }

        out.write(entityValue); // Write the unescaped character

        // Calculate the number of characters consumed from the input.
        // This includes the initial '&', '#', optional 'x', the numeric part, and the final ';'.
        // The length is (position of ';') - (start of '&') + 1.
        return (end - index) + 1;
    }
    return 0; // Not a numeric entity, return 0
}
