import org.apache.commons.lang3.StringUtils;

public class NumberUtils {

    // ... (other fields and methods from the original context)

    public static boolean isNumber(String str) {
        if (StringUtils.isEmpty(str)) {
            return false;
        }

        char[] chars = str.toCharArray();
        int sz = chars.length;
        boolean hasExp = false;
        boolean hasDecPoint = false;
        boolean allowSigns = false; // True if a sign is allowed (e.g., after 'e' or at the beginning)
        boolean foundDigit = false; // True if at least one digit has been found

        // Determine the starting index after an optional leading sign
        int start = 0;
        if (chars[0] == '-' || chars[0] == '+') { // Corrected: Handle both '-' and '+'
            start = 1;
        }

        // If the string is just a sign ("+" or "-"), it's not a number
        if (start == sz) {
            return false;
        }

        // Handle hexadecimal numbers (e.g., "0x1a", "-0xAF")
        // Need at least "0x" or "-0x" + one hex digit
        if (sz > start + 1 && chars[start] == '0' && (chars[start + 1] == 'x' || chars[start + 1] == 'X')) {
            int i = start + 2;
            if (i == sz) {
                return false; // str == "0x" or "-0x"
            }
            // checking hex (it can't be anything else)
            for (; i < chars.length; i++) {
                if (!((chars[i] >= '0' && chars[i] <= '9')
                    || (chars[i] >= 'a' && chars[i] <= 'f')
                    || (chars[i] >= 'A' && chars[i] <= 'F'))) {
                    return false;
                }
            }
            return true;
        }

        // Main loop for decimal, float, double, long
        // Loop through characters, stopping before the last one, unless it's a sign after 'E'
        // The loop processes characters from `start` up to `chars.length - 2`.
        // The character at `chars.length - 1` (the actual last character) is handled after the loop,
        // UNLESS it's a sign after 'E' and no digit has been found yet (e.g., "1E+").
        int loopEnd = chars.length - 1; // Index of the last character
        int i = start;

        while (i < loopEnd || (i == loopEnd && allowSigns && !foundDigit)) {
            if (chars[i] >= '0' && chars[i] <= '9') {
                foundDigit = true;
                allowSigns = false; // No sign allowed after a digit (unless it's an exponent sign)

            } else if (chars[i] == '.') {
                if (hasDecPoint || hasExp) {
                    // two decimal points or dec in exponent
                    return false;
                }
                hasDecPoint = true;
                // foundDigit is NOT set here. This means ".5" will not have foundDigit=true
                // until the '5' is processed, which is handled in the post-loop block.

            } else if (chars[i] == 'e' || chars[i] == 'E') {
                if (hasExp) {
                    // two E's
                    return false;
                }
                if (!foundDigit) {
                    // Must have at least one digit before 'E' (e.g., "1E", "1.2E")
                    return false;
                }
                hasExp = true;
                allowSigns = true; // A sign is allowed immediately after 'E'
                // foundDigit is NOT reset here. It will be reset if a sign follows 'E'.

            } else if (chars[i] == '+' || chars[i] == '-') {
                if (!allowSigns) {
                    // Sign only allowed at start or after 'E'
                    return false;
                }
                allowSigns = false; // Only one sign allowed in this context
                foundDigit = false; // We need a digit after the sign (e.g., "1E+5", not "1E+")
            } else {
                return false; // Invalid character
            }
            i++;
        }

        // Handle the last character (if any)
        // `i` is now `chars.length - 1` (the actual last character) or `chars.length`
        if (i < chars.length) { // This means `i` is `chars.length - 1`
            if (chars[i] >= '0' && chars[i] <= '9') {
                // No type qualifier, OK (e.g., "123", "1.23")
                // Corrected: Must have found a digit *before* this last digit,
                // or this last digit is the *only* digit and it's not part of ".5" type cases.
                // The `foundDigit` flag correctly tracks if *any* digit was found.
                // For ".5", `foundDigit` is false when '5' is processed.
                return foundDigit; // Corrected: ".5" will now return false.
            }
