public static <T> T[] add(T[] array, int index, T element) {
    Class<?> clss;

    if (array == null) {
        // If the array is null, the only valid index to add an element is 0.
        if (index != 0) {
            throw new IndexOutOfBoundsException("Cannot add to a null array at index " + index + ". Only index 0 is valid for a null array.");
        }
        // If array is null, determine the component type from the element.
        if (element != null) {
            clss = element.getClass();
        } else {
            // Both array and element are null. We cannot determine the component type
            // for the new array in a type-safe manner.
            // The original ArrayUtils returns (T[]) new Object[] { null };
            // which is type-unsafe (heap pollution).
            // A robust implementation should throw an exception.
            throw new IllegalArgumentException("Cannot determine component type when both array and element are null. " +
                                               "Provide a non-null array or element to infer the type.");
        }
    } else {
        // Array is not null. Determine component type from the existing array.
        clss = array.getClass().getComponentType();

        // Validate index for a non-null array.
        // Index must be between 0 (inclusive) and array.length (inclusive).
        if (index < 0 || index > array.length) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Array length: " + array.length);
        }
    }

    // Delegate to the private helper method which handles the actual array creation,
    // element insertion, and copying of existing elements.
    // The helper method is expected to create a new array of 'clss' type and size (array.length + 1).
    @SuppressWarnings("unchecked") // The private add method creates an array of type clss, which is type T
    final T[] newArray = (T[]) add(array, index, element, clss);
    return newArray;
}
