    // 1. Precondition check: Ensure the stopwatch is in a state where it can be stopped.
    // It must be either running or suspended. If it's unstarted or already stopped,
    // an IllegalStateException is thrown.
    if (this.runningState != STATE_RUNNING && this.runningState != STATE_SUSPENDED) {
        throw new IllegalStateException("Stopwatch is not running. It must be in a RUNNING or SUSPENDED state to be stopped.");
