public static String abbreviate(String str, int lower, int upper, String appendToEnd) {
    // Initial parameter checks
    if (str == null) {
        return null;
    }
    if (str.length() == 0) {
        return StringUtils.EMPTY;
    }

    // --- Robustness: Normalize lower and upper parameters ---

    // Ensure 'lower' is not negative.
    // 'lower' is interpreted as the minimum index from which to start searching for a space.
    if (lower < 0) {
        lower = 0;
    }

    // Ensure 'upper' is not negative, unless it's -1 (special value for no limit).
    // 'upper' is interpreted as the maximum length of the prefix before appending 'appendToEnd'.
    if (upper < -1) {
        upper = 0; // Treat invalid negative as 0, as 0 is a sensible minimum length for abbreviation.
    }

    // If 'upper' is -1 (no limit) or is greater than the string's length,
    // set it to the string's length. This means no truncation beyond the original length.
    if (upper == -1 || upper > str.length()) {
        upper = str.length();
    }

    // If 'upper' is less than 'lower', raise 'upper' to 'lower'.
    // This ensures that the maximum prefix length is at least the starting point for word search.
    // This implicitly means 'lower' acts as a minimum effective truncation point if 'upper' is too small.
    if (upper < lower) {
        upper = lower;
    }

    // --- Logical Fix: Early exit if no abbreviation is needed ---
    // If the string's length is already less than or equal to the effective 'upper' limit,
    // no abbreviation is required. Return the original string.
    if (str.length() <= upper) {
        return str;
    }

    // --- Core Abbreviation Logic ---
    // At this point, we know str.length() > upper, so abbreviation will definitely occur.

    // Use StringBuilder for better performance in modern Java for non-thread-safe string building.
    StringBuilder result = new StringBuilder();
    // Find the first space character in 'str' starting from 'lower' index.
    int wordBreakIndex = StringUtils.indexOf(str, " ", lower);

    int truncationPoint;

    // Determine the point at which to truncate the string.
    if (wordBreakIndex == -1) {
        // Case 1: No space found from 'lower' onwards.
        // Truncate strictly at the 'upper' character limit.
        truncationPoint = upper;
    } else if (wordBreakIndex > upper) {
        // Case 2: The first space found is beyond the 'upper' character limit.
        // Truncate strictly at the 'upper' character limit.
        truncationPoint = upper;
    } else { // wordBreakIndex <= upper
        // Case 3: A space was found within or at the 'upper' character limit.
        // Truncate at this word boundary.
        truncationPoint = wordBreakIndex;
    }

    // Append the determined prefix of the string.
    result.append(str.substring(0, truncationPoint));

    // --- Logical Fix: Consistent appendToEnd application ---
    // Since we've already established that str.length() > upper, and truncationPoint <= upper,
    // it implies that truncationPoint will always be less than str.length().
    // Therefore, actual abbreviation has occurred, and 'appendToEnd' should always be appended.
    result.append(StringUtils.defaultString(appendToEnd));

    return result.toString();
}
