public int compareTo(Object other) {
    // Robustness: Explicitly check for null to provide a clear NullPointerException.
    // This aligns with the Comparable contract.
    if (other == null) {
        throw new NullPointerException("Cannot compare to a null object. The 'other' object must not be null.");
    }

    // Robustness: Explicitly check the type to ensure 'other' is a ValuedEnum.
    // This prevents unexpected ClassCastException later and provides a more informative message.
    // This also aligns with the Comparable contract.
    if (!(other instanceof ValuedEnum)) {
        throw new ClassCastException("Cannot compare ValuedEnum to an object of type " + other.getClass().getName() + ". Expected ValuedEnum.");
    }

    // Cast 'other' to ValuedEnum after successful type check.
    ValuedEnum otherValuedEnum = (ValuedEnum) other;

    // Logical Fix: Use Integer.compare() to safely compare integer values.
    // This avoids potential integer overflow issues that can arise from simple subtraction,
    // ensuring correct comparison results for all possible integer values.
    return Integer.compare(this.iValue, otherValuedEnum.iValue);
}
