    // Handle null search string.
    if (str == null) {
        return -1;
    }

    // Get the length of the string to search for.
    int strLen = str.length();

    // If startIndex is at or beyond the current content size, no match is possible.
    // This also handles cases where StrBuilder is empty (size == 0) and startIndex is 0.
    if (startIndex >= size) {
        // Special case for empty search string: if startIndex is exactly size,
        // String.indexOf returns size. However, this StrBuilder's convention
        // seems to be -1 for any startIndex >= size. We maintain this.
        if (strLen == 0 && startIndex == size) {
            return size; // Aligning with String.indexOf for empty string at end
        }
        return -1;
    }

    // Optimization: If search string is a single character, delegate to the char-based indexOf.
    if (strLen == 1) {
        return indexOf(str.charAt(0), startIndex);
    }

    // Special case: Searching for an empty string.
    // An empty string is considered to be found at any valid startIndex.
    // The `startIndex >= size` check above already handles out-of-bounds `startIndex`.
    if (strLen == 0) {
        return startIndex;
    }

    // If the search string is longer than the StrBuilder's content, no match is possible.
    if (strLen > size) {
        return -1;
    }

    // Get the internal character buffer.
    char[] thisBuf = buffer;

    // Calculate the maximum possible starting index for a match.
    // The search string must fit entirely within the StrBuilder's content.
    // The last possible valid starting index is (size - strLen).
    int maxSearchIndex = size - strLen;

    // Main search loop: Iterate through possible starting positions in the StrBuilder's content.
    // The loop iterates up to and including maxSearchIndex.
    outer:
    for (int i = startIndex; i <= maxSearchIndex; i++) {
        // Inner loop: Compare characters of the search string with the StrBuilder's content.
        for (int j = 0; j < strLen; j++) {
            // If a character mismatch is found, break from the inner loop and try the next starting position.
            if (str.charAt(j) != thisBuf[i + j]) {
                continue outer;
            }
        }
        // If the inner loop completes, it means all characters matched. Return the current starting index.
        return i;
    }

    // If the outer loop completes without finding a match, return -1.
    return -1;
